INSERT INTO `diseases` (`disease_id`, `disease_name`, `disease_code`, `category`, `transmission_mode`, `severity_level`, `reporting_requirement`, `description`, `created_at`) VALUES
  (1, 'Dengue Fever', 'DIS-DEN-01', 'Vector-borne', 'Aedes mosquito bite transmission', 'Moderate', 'Immediate (24h)', 'Acute viral mosquito-borne infection with high fever, rash, and thrombocytopenia.', '2026-10-25 11:48:29'),
  (2, 'Malaria (Plasmodium falciparum)', 'DIS-MAL-02', 'Vector-borne', 'Anopheles mosquito vector', 'Severe', 'Immediate (24h)', 'Parasitic disease characterized by recurring chills, fever, anemia, and splenomegaly.', '2026-10-25 11:48:29'),
  (3, 'Chikungunya', 'DIS-CHIK-03', 'Vector-borne', 'Aedes albopictus / aegypti vector', 'Moderate', 'Weekly', 'Viral illness causing debilitating joint pain, rash, and fever.', '2026-10-25 11:48:29'),
  (4, 'COVID-19 (SARS-CoV-2)', 'DIS-COV-04', 'Airborne', 'Respiratory droplets and aerosol inhalation', 'Severe', 'Immediate (24h)', 'Novel coronavirus disease presenting respiratory distress, cough, and anosmia.', '2026-10-25 11:48:29'),
  (5, 'Pulmonary Tuberculosis', 'DIS-TB-05', 'Airborne', 'Inhalation of Mycobacterium droplet nuclei', 'Critical', 'Weekly', 'Chronic pulmonary bacterial infection marked by persistent cough, hemoptysis, and weight loss.', '2026-10-25 11:48:29'),
  (6, 'Cholera (Vibrio cholerae)', 'DIS-CHOL-06', 'Water-borne', 'Ingestion of contaminated water or food', 'Critical', 'Immediate (24h)', 'Acute diarrheal illness causing profound dehydration and hypovolemic shock.', '2026-10-25 11:48:29'),
  (7, 'Viral Hepatitis A/E', 'DIS-HEP-07', 'Water-borne', 'Fecal-oral transmission through unhygienic water', 'Moderate', 'Weekly', 'Acute hepatic inflammation resulting in jaundice, abdominal pain, and dark urine.', '2026-10-25 11:48:29'),
  (8, 'Typhoid Fever', 'DIS-TYPH-08', 'Water-borne', 'Salmonella enterica serovar Typhi ingestion', 'Moderate', 'Weekly', 'Systemic bacterial infection characterized by sustained step-ladder fever and delirium.', '2026-10-25 11:48:29'),
  (9, 'Rabies Encephalitis', 'DIS-RAB-09', 'Zoonotic', 'Saliva from infected animal bite (canine)', 'Critical', 'Immediate (24h)', 'Near-fatal neurological encephalomyelitis preventable through timely post-exposure prophylaxis.', '2026-10-25 11:48:29'),
  (10, 'Leptospirosis', 'DIS-LEP-10', 'Zoonotic', 'Direct skin contact with rodent-contaminated floodwaters', 'Severe', 'Immediate (24h)', 'Spirochetal zoonosis common during monsoon inundation causing renal and hepatic injury.', '2026-10-25 11:48:29');
