INSERT INTO `outbreak_alerts` (`alert_id`, `alert_reference`, `disease_id`, `region_id`, `alert_title`, `alert_level`, `detection_date`, `status`, `description`, `cases_threshold_exceeded`, `created_at`, `last_updated`) VALUES
  (1, 'ALT-2026-0001', 1, 1, 'Dengue Cluster Surge Detected in Urban Core', 'High', '2026-08-14', 'Monitoring', 'Cluster of 34 confirmed dengue cases within 2 km radius in Bhavani Peth and Hadapsar wards.', 25, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (2, 'ALT-2026-0002', 6, 2, 'Acute Water-borne Gastroenteritis / Cholera Signal', 'Critical', '2026-08-20', 'Open', 'Water contamination suspected following municipal pipeline breach in Govandi municipal sector.', 40, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (3, 'ALT-2026-0003', 2, 3, 'Spike in Falciparum Malaria Notifications', 'Moderate', '2026-09-02', 'Monitoring', 'Post-monsoon vector density increment noted in eastern urban fringes.', 18, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (4, 'ALT-2026-0004', 4, 1, 'Respiratory Illness Cluster in Higher Secondary School', 'Low', '2026-09-10', 'Resolved', 'Cluster of mild febrile respiratory illness resolved after 7-day isolation and symptom monitoring.', 8, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (5, 'ALT-2026-0005', 10, 5, 'Leptospirosis Alert Post Waterlogging', 'High', '2026-09-18', 'Open', 'Elevated clinical presentations of suspected leptospirosis among sanitation and fieldwork personnel.', 22, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (6, 'ALT-2026-0006', 8, 4, 'Typhoid Fever Outbreak Linked to Commercial Food Facility', 'Moderate', '2026-09-22', 'Monitoring', 'Epidemiological traceback connects 19 enteric fever notifications to street vendor intersection.', 15, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (7, 'ALT-2026-0007', 3, 6, 'Chikungunya Arthralgia Surge in Cantonment Zone', 'Moderate', '2026-09-28', 'Monitoring', 'Entomological larval index exceeds critical threshold (Breteau Index > 30).', 16, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (8, 'ALT-2026-0008', 7, 7, 'Hepatitis A Cluster in Residential Hostel', 'Low', '2026-10-02', 'Resolved', 'Overhead reservoir sanitized; containment measures enacted successfully.', 9, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (9, 'ALT-2026-0009', 1, 8, 'Dengue Warning in Agricultural Periphery', 'Moderate', '2026-10-06', 'Open', 'Rising seropositive IgM ELISA reports reported from rural taluka health posts.', 14, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (10, 'ALT-2026-0010', 9, 9, 'Suspected Canine Rabies Exposure Threat', 'Critical', '2026-10-12', 'Open', 'Stray animal aggression incident with 5 individuals requiring urgent RIG and cell culture vaccine.', 5, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (11, 'ALT-2026-0011', 5, 2, 'Multidrug-Resistant TB Surveillance Scrutiny', 'High', '2026-10-15', 'Monitoring', 'Cohort review demonstrates clustering of secondary contacts requiring active screening.', 12, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (12, 'ALT-2026-0012', 2, 10, 'Malaria Spike in Tribal Forest Blocks', 'High', '2026-10-18', 'Open', 'Seasonal migratory labor return correlated with surge in falciparum blood smears.', 28, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (13, 'ALT-2026-0013', 1, 11, 'Dengue Micro-Cluster in Suburban Housing Society', 'Informational', '2026-10-20', 'Open', 'Preventative vector fogging requested by regional health inspector.', 6, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (14, 'ALT-2026-0014', 6, 12, 'Diarrheal Disease Advisory Coastal Fishing Hamlets', 'Moderate', '2026-10-21', 'Monitoring', 'Bacterial culture isolates indicate contamination of shallow borewell waters.', 17, '2026-10-25 11:48:29', '2026-10-25 11:48:29'),
  (15, 'ALT-2026-0015', 4, 3, 'COVID-19 Variant Genomic Watch', 'Low', '2026-10-22', 'Open', 'Routine sewage surveillance detected slight spike in viral RNA copy numbers.', 10, '2026-10-25 11:48:29', '2026-10-25 11:48:29');
